// off/offEn = FF13_BTSC_NO_TEXT when this row has no string in that language.
// order = where the row sat in the TSV, which IS the order the picker lists them in.
// mode = 0 for the fight itself, 1..n for the row that pins one of its forms. Rows are
// sorted on (btsc, mode), which is the key the picker searches them with -- the order
// they are SHOWN in is the field, not the position.
#define FF13_BTSC_NO_TEXT    0xFFFFFFFFu
